def write(name,value):
    text=json.dumps(value,ensure_ascii=False,indent=2)+'\n'
    with (OUT/name).open('x',encoding='utf8') as f:f.write(text)
def issues(text):
    result={}
    for m in re.finditer(r'^### ([^\r\n]+)\r?\n([\s\S]*?)(?=^### |\Z)',text,re.M):
        s=re.search(r'Статус: \*\*([^*]+)\*\*',m[2])
        if s:result[m[1]]=dict(status=s[1],body=m[2])
    return result
